public class URLValidator extends FieldValidatorSupport {

    private static final Logger LOG = Logger.getLogger(URLValidator.class.getName());

    private String urlRegex;
    private String urlRegexExpression;

    // other methods

    /**
     * This is used to support client‑side validation, it's based on
     * http://stackoverflow.com/questions/161738/what-is-the-best-regular-expression-to-check-if-a-string-is-a-valid-url
     *
     * @return regex to validate URLs
     */
    public String getUrlRegex() {
        // Prefer a user supplied expression if it is non‑null and non‑empty
        if (urlRegexExpression != null && !urlRegexExpression.isEmpty()) {
            try {
                Object parsed = parse(urlRegexExpression, String.class);
                if (parsed instanceof String) {
                    return (String) parsed;
                } else {
                    LOG.log(Level.WARNING,
                            "Parsed urlRegexExpression did not return a String: {0}",
                            urlRegexExpression);
                }
            } catch (Exception e) {
                LOG.log(Level.SEVERE,
                        "Failed to parse urlRegexExpression: " + urlRegexExpression, e);
            }
        }

        // Fallback to the legacy regex if it is non‑null and non‑empty
        if (urlRegex != null && !urlRegex.isEmpty()) {
            return urlRegex;
        }

        // Default safe regex – matches only an empty string
        // This ensures the validator never throws a NullPointerException
        // and provides a predictable, conservative behaviour.
        return "^(?:)$";
    }

    // other methods
}
