import java.nio.file.Paths;

/**
 * Utility class for importing files safely.
 */
public class ImportingUtilities {

    // other methods

    /**
     * Allocates a new {@link File} inside {@code dir} with a name derived from {@code name}.
     * The method sanitizes {@code name} to prevent directory‑traversal attacks and ensures
     * that the resulting file resides within {@code dir}. If a file with the same name
     * already exists, a numeric suffix is appended until a unique name is found.
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the desired file name (may contain query parameters)
     * @return a {@link File} instance pointing to a unique file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null}
     * @throws SecurityException        if the sanitized name resolves outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        /* Strip query parameters (e.g., "file.txt?foo=bar") */
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        /* Normalize the supplied path and guard against absolute paths or
         * traversal sequences such as "../".  The resulting Path must be
         * relative and must not start with "..". */
        Path rawPath = Paths.get(name).normalize();
        if (rawPath.isAbsolute() || rawPath.startsWith("..")) {
            throw new SecurityException("Invalid file name: " + name);
        }

        /* Convert the Path back to a string and replace any remaining
         * path separators with an underscore to guarantee a single file
         * name without subdirectories. */
        String sanitized = rawPath.toString().replaceAll("[\\\\/]", "_");
        if (sanitized.isEmpty()) {
            throw new IllegalArgumentException("File name cannot be empty after sanitization");
        }

        /* Construct the initial File object. */
        File file = new File(dir, sanitized);

        /* Determine prefix and suffix for generating unique names. */
        int dot = sanitized.lastIndexOf('.');
        String prefix = dot < 0 ? sanitized : sanitized.substring(0, dot);
        String suffix = dot < 0 ? "" : sanitized.substring(dot);

        /* Append a numeric suffix until a non‑existing file name is found. */
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        /* Ensure the parent directory exists. */
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            if (!parent.mkdirs()) {
                throw new RuntimeException("Failed to create directories: " + parent);
            }
        }

        return file;
    }

    // other methods
}
