    /**
     * Safely expands entries from the supplied archive into the target directory.
     *
     * <p>This method performs rigorous path validation to prevent path‑traversal attacks.
     * It normalizes entry names, rejects absolute paths and any component containing
     * {@code ..}, and verifies that the resolved absolute path of each entry
     * resides within the canonical target directory. Directory creation and file
     * extraction are performed using the NIO API, which provides better handling
     * of symbolic links and platform differences.</p>
     *
     * @param supplier      provides archive entries to read
     * @param writer        writes entry data to an output stream
     * @param targetDirectory the root directory where entries will be extracted
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical (real) path of the target directory once.
        Path targetDirReal = targetDirectory.toPath().toRealPath(LinkOption.NOFOLLOW_LINKS);

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {

            // ---- Sanitize the entry name ------------------------------------
            String rawName = nextEntry.getName();

            if (rawName == null || rawName.isEmpty()) {
                // Skip empty or null names – they cannot be safely processed.
                nextEntry = supplier.getNextReadableEntry();
                continue;
            }

            // Reject absolute paths (both Unix and Windows styles).
            if (rawName.startsWith("/") || rawName.startsWith("\\") ||
                rawName.matches("^[a-zA-Z]:[\\\\/].*")) {
                throw new IOException("Entry name is absolute: " + rawName);
            }

            // Normalize separators to forward slashes for consistent handling.
            String normalizedName = rawName.replace('\\', '/');

            // Reject any component that attempts to traverse upwards.
            if (normalizedName.contains("..")) {
                throw new IOException("Entry name contains forbidden component '..': " + rawName);
            }

            // ---- Resolve the full path of the entry -------------------------
            Path entryPath = targetDirReal.resolve(normalizedName).normalize();

            // Ensure the resolved path is still within the target directory.
            if (!entryPath.startsWith(targetDirReal)) {
                throw new IOException(
                        "Expanding " + rawName + " would create file outside of "
                                + targetDirectory.getAbsolutePath());
            }

            // ---- Handle directories ------------------------------------------
            if (nextEntry.isDirectory()) {
                if (!Files.exists(entryPath)) {
                    try {
                        Files.createDirectories(entryPath);
                    } catch (IOException e) {
                        throw new IOException("Failed to create directory " + entryPath, e);
                    }
                }
            } else { // ---- Handle regular files --------------------------------
                Path parent = entryPath.getParent();
                if (parent != null && !Files.exists(parent)) {
                    try {
                        Files.createDirectories(parent);
                    } catch (IOException e) {
                        throw new IOException("Failed to create directory " + parent, e);
                    }
                }

                try (OutputStream out = Files.newOutputStream(entryPath)) {
                    writer.writeEntryDataTo(nextEntry, out);
                } catch (IOException e) {
                    throw new IOException("Failed to write file " + entryPath, e);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

