    public Calendar ceil(Calendar cal) {
        // Create a clone of the input calendar to represent a date two years in the future.
        Calendar twoYearsFuture = (Calendar) cal.clone();
        // Set the future date limit to two years from the current calendar date.
        twoYearsFuture.add(Calendar.YEAR, 2);

        // Safety guard to prevent infinite loops – limit the number of iterations.
        final int MAX_ITERATIONS = 1000;
        int iterations = 0;

        OUTER: while (iterations++ < MAX_ITERATIONS) {

            // If the date exceeds the two‑year future limit, it is considered too rare or impossible.
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
            }

            boolean changed = false;          // Tracks whether any field was modified in this pass.
            boolean redoNeeded = false;       // Indicates if a full restart of the adjustment cycle is required.

            // Iterate over each CalendarField in the predefined adjustment order to modify the calendar date.
            for (CalendarField f : CalendarField.ADJUST_ORDER) {

                int cur = f.valueOf(cal);
                int next = f.ceil(this, cur);

                // No adjustment needed for this field.
                if (cur == next) {
                    continue;
                }

                // Mark that a change has occurred.
                changed = true;

                // Clear all lower fields if the current field value changes.
                for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                    l.clear(cal);
                }

                // Handle cases where the next value is invalid (negative).
                if (next < 0) {
                    f.rollUp(cal, 1);
                    f.setTo(cal, f.first(this));
                    redoNeeded = true;   // Must restart the adjustment process.
                    continue OUTER;
                } else {
                    f.setTo(cal, next);
                    if (f.redoAdjustmentIfModified) {
                        redoNeeded = true;
                    }
                }
            }

            // If no fields were changed during this pass, the calendar is now valid.
            if (!changed) {
                return cal;
            }

            // If a field modification requires a full restart, continue the outer loop.
            if (redoNeeded) {
                continue OUTER;
            }

            // Otherwise, the calendar is valid and can be returned.
            return cal;
        }

        // If we reach here, the loop exceeded the maximum allowed iterations – treat as a failure.
        throw new IllegalStateException("Ceil operation exceeded maximum iterations, possible infinite loop detected.");
