            // Disable namespace prefixes to avoid unnecessary complexity
            setFeatureSafe(parser, "http://xml.org/sax/features/namespaces", true);
            setFeatureSafe(parser, "http://xml.org/sax/features/namespace-prefixes", true);

            // Disable validation – validation requires DTDs which we are blocking
            setFeatureSafe(parser, "http://xml.org/sax/features/validation", isValidating);

            // Prevent external entity resolution
            setFeatureSafe(parser, "http://xml.org/sax/features/external-general-entities", false);
            setFeatureSafe(parser, "http://xml.org/sax/features/external-parameter-entities", false);

            // Completely disallow DOCTYPE declarations (prevents DTD processing)
            setFeatureSafe(parser, "http://apache.org/xml/features/disallow-doctype-decl", true);

            // Do not load external DTDs or DTD grammars
            setFeatureSafe(parser, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            setFeatureSafe(parser, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);

